async function invoice(id){let [d,publicLink]=await Promise.all([api('/api/admin/orders/'+id),api('/api/admin/orders/'+id+'/public-link')]),o=d.order,items=d.items||[];let site=location.origin,orderUrl=site+(publicLink.path||'/order/'+id);let payment=String(o.payment_method||'cash').toLowerCase()==='visa'?'Visa':'الدفع عند الاستلام';let region={westbank:'الضفة',jerusalem:'القدس',inside:'الداخل'}[String(o.shipping_region||'').toLowerCase()]||o.shipping_region||'-';let shipping=o.shipping_waived?'معفى':M(o.shipping_cost||0);$('#print').innerHTML=`<div class="printhead"><h1>Ladies First</h1><div>فاتورة #${id}<br>${new Date(o.created_at).toLocaleString('ar')}</div></div><p>العميل: ${E(o.user_name||o.customer_name||'-')}<br>الهاتف: ${E(o.user_phone||o.customer_phone||'-')}<br>البريد: ${E(o.user_email||'-')}<br>العنوان: ${E(o.shipping_address||'-')}<br>منطقة التوصيل: ${E(region)}<br>طريقة الدفع: ${E(payment)}</p>${table(['المنتج','الخيار','الكمية','السعر','الإجمالي'],items.map(i=>`<tr><td>${E(i.product_name||'-')}</td><td>${E(i.variant_name||'-')}</td><td>${i.quantity}</td><td>${M(i.unit_price)}</td><td>${M(i.total)}</td></tr>`))}<div class="invoiceTotals"><p>المجموع الفرعي: <b>${M(o.subtotal||0)}</b></p><p>خصم الكوبون${o.coupon_code?' ('+E(o.coupon_code)+')':''}: <b>-${M(o.coupon_discount||0)}</b></p><p>خصم Visa: <b>-${M(o.visa_discount||0)}</b></p><p>خصم نقاط الولاء${Number(o.points_redeemed||0)>0?' ('+Number(o.points_redeemed)+' نقطة)':''}: <b>-${M(o.loyalty_discount||0)}</b></p><p>التغليف: <b>${M(o.packaging_cost||0)}</b></p><p>رسوم التوصيل الأصلية (${E(region)}): <b>${M(o.shipping_base_cost??o.shipping_cost??0)}</b></p><p>خصم التوصيل${Number(o.shipping_discount_percent||0)>0?' ('+M(o.shipping_discount_percent)+'%)':''}: <b>-${M(o.shipping_discount_amount||0)}</b></p><p>المستحق لشركة التوصيل: <b>${shipping}</b></p><p><b>الإجمالي النهائي: ${M(o.total)}</b></p></div><div class="qrrow"><div><div id="qrsite"></div><b>زوروا موقعنا</b></div><div><div id="qrorder"></div><b>تفاصيل طلبك</b></div></div>`;new QRCode($('#qrsite'),{text:site,width:145,height:145});new QRCode($('#qrorder'),{text:orderUrl,width:145,height:145});window.print()}
function invoicePrompt(){let id=prompt('أدخل رقم الطلب');if(id)invoice(Number(id))}
let adminReturnRequests=[],adminReturnProducts=[];
