async function reports(){let t=new Date().toISOString().slice(0,10);$('#sections').innerHTML=`<div class="card"><h2>تقارير المبيعات والأرباح</h2><div class="toolbar"><input id="rf" type="date" class="field" value="${t}" onchange="reportRun()"><input id="rt" type="date" class="field" value="${t}" onchange="reportRun()"></div><div id="rr"></div></div>`;reportRun()}async function reportRun(){let d=await api('/api/admin/reports/sales?from='+$('#rf').value+'&to='+$('#rt').value),s=d.summary||{};$('#rr').innerHTML=`<div class="cards"><div class="stat">الطلبات<b>${s.orders||0}</b></div><div class="stat">صافي المبيعات<b>${M(s.sales)}</b></div><div class="stat">صافي التكلفة<b>${M(s.cost)}</b></div><div class="stat">صافي الربح<b>${M(s.profit)}</b></div><div class="stat">المرتجعات<b>${M(s.returnsValue)}</b></div><div class="stat">فرق الاستبدال<b>${M(s.exchangeDifference)}</b></div><div class="stat">الملغاة<b>${s.cancelled||0}</b></div></div>`+table(['التاريخ','الطلبات','المبيعات','التكلفة','الربح'],(d.rows||[]).map(x=>`<tr><td>${x.date}</td><td>${x.orders}</td><td>${M(x.sales)}</td><td>${M(x.cost)}</td><td>${M(x.profit)}</td></tr>`))}
let adminPackagingOptions=[];
function capturePackagingOptions(){adminPackagingOptions=[...document.querySelectorAll('.packagingAdminRow')].map((row,i)=>({id:row.dataset.id||('package-'+(i+1)),nameAr:row.querySelector('.pkgAr').value.trim(),nameEn:row.querySelector('.pkgEn').value.trim(),price:Math.max(0,Number(row.querySelector('.pkgPrice').value)||0),active:row.querySelector('.pkgActive').checked})).filter(x=>x.nameAr||x.nameEn)}
function renderPackagingAdmin(){const box=$('#packagingAdminRows');if(!box)return;box.innerHTML=adminPackagingOptions.map((x,i)=>`<div class="card packagingAdminRow" data-id="${E(x.id||('package-'+(i+1)))}"><div class="formgrid"><input class="field pkgAr" value="${E(x.nameAr||'')}" placeholder="اسم التغليف بالعربية"><input class="field pkgEn" value="${E(x.nameEn||'')}" placeholder="English name"><input class="field pkgPrice" type="number" min="0" step=".01" value="${Number(x.price)||0}" placeholder="السعر"><label><input class="pkgActive" type="checkbox" ${x.active===false?'':'checked'}> فعال</label></div><button class="btn" type="button" onclick="removePackagingOption(${i})">حذف</button></div>`).join('')||'<p>لا توجد خيارات تغليف.</p>'}
function addPackagingOption(){capturePackagingOptions();adminPackagingOptions.push({id:'package-'+Date.now(),nameAr:'تغليف جديد',nameEn:'New wrapping',price:0,active:true});renderPackagingAdmin()}
function removePackagingOption(i){capturePackagingOptions();adminPackagingOptions.splice(i,1);renderPackagingAdmin()}
async function settings(){let d=await api('/api/admin/settings'),s=d.settings||{};adminPackagingOptions=Array.isArray(s.packaging_options)?s.packaging_options.map(x=>({...x})):[{id:'clear-ribbon',nameAr:'تغليف شفاف مع شبرة',nameEn:'Clear wrapping with ribbon',price:5,active:true},{id:'paper-ribbon',nameAr:'تغليف ورقي مع شبرة',nameEn:'Paper wrapping with ribbon',price:15,active:true}];$('#sections').innerHTML=`<div class="grid"><div class="card"><h2>الإعدادات</h2><div class="formgrid"><input id="stn" class="field" value="${E(s.store_name||'Ladies First')}" placeholder="اسم المتجر"><input id="stp" class="field" value="${E(s.phone||'')}" placeholder="الهاتف"><input id="stw" class="field" value="${E(s.whatsapp||s.whatsapp_number||'0562499924')}" placeholder="WhatsApp"><input id="cur" class="field" value="${E(s.currency||'₪')}" placeholder="العملة"><textarea id="rp" class="field full" rows="5" placeholder="سياسة الاستبدال">${E(s.return_policy||'')}</textarea></div></div><div class="card"><h2>رسوم التوصيل</h2><p>هذه الأسعار يعتمدها الـBackend عند إنشاء الطلب.</p><div class="formgrid"><label>الضفة<input id="shipWestbank" class="field" type="number" min="0" step=".01" value="${Number(s.shipping_fees?.westbank??20)}"></label><label>القدس<input id="shipJerusalem" class="field" type="number" min="0" step=".01" value="${Number(s.shipping_fees?.jerusalem??35)}"></label><label>الداخل<input id="shipInside" class="field" type="number" min="0" step=".01" value="${Number(s.shipping_fees?.inside??70)}"></label><label>خصم توصيل الضفة %<input id="shipDiscountWestbank" class="field" type="number" min="0" max="100" step=".1" value="${Number(s.shipping_discount_percentages?.westbank??0)}"></label><label>خصم توصيل القدس %<input id="shipDiscountJerusalem" class="field" type="number" min="0" max="100" step=".1" value="${Number(s.shipping_discount_percentages?.jerusalem??0)}"></label><label>خصم توصيل الداخل %<input id="shipDiscountInside" class="field" type="number" min="0" max="100" step=".1" value="${Number(s.shipping_discount_percentages?.inside??0)}"></label></div><p>رسوم التوصيل مبالغ محصّلة لصالح شركة التوصيل ولا تدخل ضمن ربح المتجر.</p></div><div class="card"><h2>نقاط الولاء</h2><label class="toolbar"><input id="loyaltyEnabled" type="checkbox" ${s.loyalty_enabled===false?'':'checked'}> تفعيل برنامج الولاء</label><label class="toolbar"><input id="loyaltyRedeem" type="checkbox" ${s.loyalty_redeem_enabled===false?'':'checked'}> السماح باستبدال النقاط عند الدفع</label><div class="formgrid"><label>طريقة الكسب<select id="loyaltyMode" class="field"><option value="amount" ${String(s.loyalty_earning_mode||'amount')==='amount'?'selected':''}>حسب قيمة الطلب</option><option value="order" ${String(s.loyalty_earning_mode||'amount')==='order'?'selected':''}>عدد ثابت لكل طلب</option></select></label><label>نقاط لكل 1 ₪<input id="loyaltyRate" class="field" type="number" min="0" step=".01" value="${Number(s.loyalty_points_per_currency??1)}"></label><label>نقاط لكل طلب<input id="loyaltyPerOrder" class="field" type="number" min="0" step="1" value="${Number(s.loyalty_points_per_order??10)}"></label><label>قيمة النقطة بالشيكل<input id="loyaltyPointValue" class="field" type="number" min="0" step=".01" value="${Number(s.loyalty_point_value??0.1)}"></label><label>خصم Visa %<input id="visaDiscount" class="field" type="number" min="0" max="100" step=".1" value="${Number(s.visa_discount_percent??0)}"></label></div></div><div class="card"><h2>خيارات تغليف الهدايا</h2><p>الأسعار هنا هي الأسعار المعتمدة في الفاتورة والـBackend.</p><div id="packagingAdminRows"></div><button class="btn" type="button" onclick="addPackagingOption()">+ خيار تغليف</button></div><div class="card"><h2>أتمتة السلة وواتساب</h2><label class="toolbar"><input id="abandonedWa" type="checkbox" ${s.abandoned_cart_whatsapp_enabled===true?'checked':''}> تفعيل تذكير السلة المتروكة بعد 7 أيام</label><label class="toolbar"><input id="lowStockWa" type="checkbox" ${s.low_stock_whatsapp_enabled===true?'checked':''}> تفعيل تنبيه المنتجات القريبة من النفاد داخل السلة</label><p>لن يدخل أي عميل في التنبيهات إلا بعد موافقته على رسائل واتساب من حسابه.</p><div class="actions"><button class="btn" onclick="cartReminders()">عرض التنبيهات المستحقة</button></div></div><div class="card"><h2>أمان الحساب</h2><p>تغيير كلمة المرور يتطلب كلمة المرور الحالية. الحد الأدنى 12 خانة.</p><div class="formgrid"><input id="cpCurrent" class="field" type="password" placeholder="كلمة المرور الحالية"><input id="cpNew" class="field" type="password" minlength="12" placeholder="كلمة المرور الجديدة"></div><div class="actions"><button class="btn primary" onclick="changeOwnPassword()">تغيير كلمة المرور</button></div><hr><h3>🔐 الدخول بالبصمة / قفل الجهاز</h3><div id="adminPasskeyStatus" class="notice">جاري التحقق من حالة البصمة…</div><div class="actions"><button class="btn" type="button" onclick="enableAdminPasskey()">تفعيل بصمة هذا الجهاز</button></div></div></div><div class="actions"><button class="btn primary" onclick="saveSettings()">حفظ كل الإعدادات</button></div>`;renderPackagingAdmin();loadAdminPasskeyStatus()}
async function loadAdminPasskeyStatus(){const el=$('#adminPasskeyStatus');if(!el)return;if(!window.LFPasskeys?.supported()){el.textContent='البصمة غير مدعومة على هذا الجهاز أو المتصفح.';return}try{const d=await api('/api/passkeys/status'),list=d.credentials||[];el.innerHTML=list.length?'البصمة مفعلة على '+list.length+' جهاز/مفتاح.'+list.map(x=>`<div class="toolbar"><span>${E(x.label||'هذا الجهاز')}</span><button class="btn" type="button" onclick="removeAdminPasskey('${E(x.id)}')">حذف</button></div>`).join(''):'لم يتم تفعيل بصمة دخول لهذا الحساب بعد.'}catch(e){el.textContent=e.message||'تعذر تحميل حالة البصمة'}}
async function enableAdminPasskey(){if(!window.LFPasskeys?.supported())return alert('هذا الجهاز أو المتصفح لا يدعم تسجيل الدخول بالبصمة.');try{const options=await api('/api/passkeys/register/options',{method:'POST',body:'{}'}),credential=await window.LFPasskeys.createCredential(options);await api('/api/passkeys/register/verify',{method:'POST',body:JSON.stringify({challengeId:options.challengeId,credential,label:'جهاز الإدارة'})});toast('تم تفعيل الدخول بالبصمة');await loadAdminPasskeyStatus()}catch(e){alert(e?.name==='NotAllowedError'?'تم إلغاء طلب البصمة أو انتهت المهلة.':(e.message||'تعذر تفعيل البصمة'))}}
async function removeAdminPasskey(id){if(!confirm('حذف هذه البصمة من حساب الإدارة؟'))return;try{await api('/api/passkeys/'+encodeURIComponent(id),{method:'DELETE'});toast('تم حذف البصمة');await loadAdminPasskeyStatus()}catch(e){alert(e.message||'تعذر حذف البصمة')}}
async function saveSettings(){capturePackagingOptions();const body={store_name:$('#stn').value,phone:$('#stp').value,whatsapp:$('#stw').value,whatsapp_number:$('#stw').value,currency:$('#cur').value,return_policy:$('#rp').value,abandoned_cart_whatsapp_enabled:!!$('#abandonedWa')?.checked,low_stock_whatsapp_enabled:!!$('#lowStockWa')?.checked,loyalty_enabled:!!$('#loyaltyEnabled')?.checked,loyalty_redeem_enabled:!!$('#loyaltyRedeem')?.checked,loyalty_earning_mode:$('#loyaltyMode').value==='order'?'order':'amount',loyalty_points_per_currency:Math.max(0,Number($('#loyaltyRate').value)||0),loyalty_points_per_order:Math.max(0,Math.floor(Number($('#loyaltyPerOrder').value)||0)),loyalty_point_value:Math.max(0,Number($('#loyaltyPointValue').value)||0),visa_discount_percent:Math.min(100,Math.max(0,Number($('#visaDiscount').value)||0)),shipping_fees:{westbank:Math.max(0,Number($('#shipWestbank').value)||0),jerusalem:Math.max(0,Number($('#shipJerusalem').value)||0),inside:Math.max(0,Number($('#shipInside').value)||0)},shipping_discount_percentages:{westbank:Math.min(100,Math.max(0,Number($('#shipDiscountWestbank').value)||0)),jerusalem:Math.min(100,Math.max(0,Number($('#shipDiscountJerusalem').value)||0)),inside:Math.min(100,Math.max(0,Number($('#shipDiscountInside').value)||0))},packaging_options:adminPackagingOptions};await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(body)});toast('تم حفظ الإعدادات');}
async function cartReminders(){const d=await api('/api/admin/cart-reminders');const abandoned=d.abandoned||[],low=d.lowStock||[];modal('تنبيهات السلة',`<div class="cards"><div class="stat">سلات متروكة<b>${abandoned.length}</b></div><div class="stat">قرب نفاد<b>${low.length}</b></div></div><h3>بعد 7 أيام</h3>${table(['العميل','الهاتف','القطع','آخر نشاط'],abandoned.map(x=>`<tr><td>${E(x.name||'-')}</td><td>${E(x.phone||'-')}</td><td>${x.itemCount||0}</td><td>${x.lastActivityAt?new Date(x.lastActivityAt).toLocaleString('ar'):'-'}</td></tr>`))}<h3>منتجات قربت تخلص</h3>${table(['العميل','الهاتف','المنتجات'],low.map(x=>`<tr><td>${E(x.name||'-')}</td><td>${E(x.phone||'-')}</td><td>${(x.lowStockItems||[]).map(i=>E((i.productName||'منتج')+' — متوفر '+i.stock)).join('<br>')}</td></tr>`))}`)}
async function social(){let d=await api('/api/admin/settings'),s=d.settings?.social_links||d.settings?.social||{};$('#sections').innerHTML=`<div class="card"><h2>مواقع التواصل</h2><p>الروابط المحفوظة هنا تظهر في الشريط الجانبي للمتجر.</p>${['whatsapp','instagram','snapchat','facebook','tiktok'].map(k=>`<div class="toolbar"><input id="s_${k}" class="field" value="${E(s[k]?.url||s[k]||'')}" placeholder="${k} URL"><label><input id="e_${k}" type="checkbox" ${s[k]?.enabled===false?'':'checked'}> فعال</label></div>`).join('')}<button class="btn primary" onclick="saveSocial()">حفظ</button></div>`}async function saveSocial(){let social_links={};['whatsapp','instagram','snapchat','facebook','tiktok'].forEach(k=>social_links[k]={url:$('#s_'+k).value.trim(),enabled:$('#e_'+k).checked});await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({social_links})});toast('تم حفظ مواقع التواصل')}
async function staff(){let d=await api('/api/admin/staff'),isOwner=String(currentAdminUser?.role||'').toLowerCase()==='owner';$('#sections').innerHTML=`<div class="card"><h2>الموظفون والصلاحيات</h2>${isOwner?'<button class="btn primary" onclick="staffForm()">+ موظف</button>':''}${table(['الاسم','البريد','الهاتف','الدور','الصلاحيات','الحالة',''],(d.staff||[]).map(x=>`<tr><td>${E(x.name)}</td><td>${E(x.email)}</td><td>${E(x.phone||'-')}</td><td>${E(x.role)}</td><td>${E(staffPermissionText(x))}</td><td>${x.is_active?'فعال':'متوقف'}</td><td>${isOwner&&x.role!=='owner'?`<button class="btn" onclick='editStaff(${JSON.stringify(x)})'>تعديل الصلاحيات</button>`:''}</td></tr>`))}</div>`}
function staffForm(){modal('موظف جديد',`<div class="formgrid"><input id="sn" class="field" placeholder="الاسم"><input id="se" class="field" placeholder="البريد"><input id="sp" class="field" placeholder="الهاتف"><input id="sw" class="field" type="password" minlength="12" placeholder="كلمة المرور — 12 خانة على الأقل"><select id="sr" class="field"><option value="staff">موظف بصلاحيات محددة</option><option value="admin">Admin — كل الصلاحيات</option></select></div><h3>صلاحيات الموظف</h3><div class="formgrid">${permissionChecks([])}</div><div class="actions"><button class="btn primary" onclick="saveStaff()">حفظ</button></div>`)}
async function saveStaff(){const password=$('#sw').value||'';if(password.length<12)return alert('كلمة المرور يجب أن تكون 12 خانة على الأقل');await api('/api/admin/staff',{method:'POST',body:JSON.stringify({name:$('#sn').value,email:$('#se').value,phone:$('#sp').value,password,role:$('#sr').value,permissions:selectedStaffPermissions()})});closeModal();toast('تم إنشاء الموظف');staff()}
function editStaff(x){modal('تعديل صلاحيات '+E(x.name||''),`<div class="formgrid"><select id="esr" class="field"><option value="staff" ${x.role==='staff'?'selected':''}>موظف بصلاحيات محددة</option><option value="admin" ${x.role==='admin'?'selected':''}>Admin — كل الصلاحيات</option></select><label style="display:flex;gap:8px;align-items:center"><input id="esa" type="checkbox" ${x.is_active?'checked':''}> الحساب فعال</label></div><h3>الصلاحيات</h3><div class="formgrid">${permissionChecks(x.permissions||[])}</div><div class="actions"><button class="btn primary" onclick="saveStaffEdit(${Number(x.id)})">حفظ التعديلات</button></div>`)}
async function saveStaffEdit(id){await api('/api/admin/staff/'+id,{method:'PATCH',body:JSON.stringify({role:$('#esr').value,is_active:!!$('#esa').checked,permissions:selectedStaffPermissions()})});closeModal();toast('تم تحديث الصلاحيات');staff()}
async function offers(){let preview={recipients:0,configured:false};try{preview=await api('/api/admin/whatsapp-campaigns/preview')}catch{}$('#sections').innerHTML=`<div class="card"><h2>العروض والحملات</h2><p>الإرسال يتم فقط للعملاء الذين وافقوا على رسائل واتساب. المستلمون الحاليون: <b>${preview.recipients||0}</b>. حالة الربط: <b>${preview.configured?'جاهز':'غير مكتمل'}</b>.</p><div class="formgrid"><input id="ot" class="field" placeholder="عنوان العرض"><input id="ol" class="field" placeholder="رابط العرض"><textarea id="om" class="field full" rows="5" placeholder="رسالة الحملة"></textarea></div><div class="actions"><button class="btn" onclick="previewCampaign()">تحديث عدد المستلمين</button><button class="btn primary" onclick="sendCampaign()" ${preview.configured?'':'disabled'}>إرسال واتساب للموافقين</button></div><div id="campaignResult"></div></div>`}
async function previewCampaign(){const d=await api('/api/admin/whatsapp-campaigns/preview');$('#campaignResult').innerHTML=`<div class="notice">المستلمون الموافقون حاليًا: <b>${d.recipients||0}</b> — الربط: <b>${d.configured?'جاهز':'غير مكتمل'}</b></div>`}
async function sendCampaign(){const title=$('#ot')?.value.trim()||'',message=$('#om')?.value.trim()||'',link=$('#ol')?.value.trim()||'';if(!title||!message)return alert('أدخل عنوان العرض ورسالة الحملة');const p=await api('/api/admin/whatsapp-campaigns/preview');if(!p.configured)return alert('ربط WhatsApp Business أو قالب الحملة غير مكتمل');if(!p.recipients)return alert('لا يوجد عملاء موافقون على رسائل واتساب حاليًا');if(!confirm('سيتم إرسال الحملة إلى '+p.recipients+' عميل موافق. متابعة؟'))return;$('#campaignResult').innerHTML='<div class="notice">جاري الإرسال...</div>';try{const d=await api('/api/admin/whatsapp-campaigns',{method:'POST',body:JSON.stringify({title,message,link,confirm:true})}),r=d.result||{};$('#campaignResult').innerHTML=`<div class="success">تم الإرسال: ${r.sent||0} — فشل: ${r.failed||0} — المستلمون: ${r.recipients||0}</div>`}catch(e){$('#campaignResult').innerHTML=`<div class="notice">${E(e.message||'تعذر إرسال الحملة')}</div>`}}
function homepage(){$('#sections').innerHTML='<div class="card"><h2>الصفحة الرئيسية</h2><p>إدارة البنرات والمحتوى وTop 5 والأكثر مبيعًا تحتاج ربط مخطط المحتوى الفعلي الموجود في قاعدة البيانات، ولن أضيف تخزينًا وهميًا.</p></div>'}
function waitStatusLabel(s){return s==='notified'?'تم الإشعار':s==='closed'?'مغلق':'بانتظار التوفر'}
async function waitlist(){const status=$('#wls')?.value||'',search=$('#wlq')?.value||'',d=await api('/api/admin/waitlist?status='+encodeURIComponent(status)+'&search='+encodeURIComponent(search));$('#sections').innerHTML=`<div class="card"><h2>قائمة التوفر</h2><p>طلبات الزبائن محفوظة في قاعدة البيانات وليست على الجهاز فقط.</p><div class="toolbar"><input id="wlq" class="field" placeholder="بحث بالمنتج أو الاسم أو الهاتف" value="${E(search)}"><select id="wls" class="field"><option value="" ${status===''?'selected':''}>كل الحالات</option><option value="waiting" ${status==='waiting'?'selected':''}>بانتظار التوفر</option><option value="notified" ${status==='notified'?'selected':''}>تم الإشعار</option><option value="closed" ${status==='closed'?'selected':''}>مغلق</option></select><button class="btn primary" onclick="waitlist()">تحديث</button></div>${table(['المنتج','الزبون','الهاتف','الخيار','الحالة','التاريخ',''],(d.requests||[]).map(x=>`<tr><td><button class="btn" onclick="window.open('/#product-${Number(x.productId)}','_blank')">${x.productImage?`<img src="${E(x.productImage)}" alt="" style="width:42px;height:42px;object-fit:cover;border-radius:8px;vertical-align:middle;margin-left:6px">`:''}${E(x.productName||'منتج')}</button></td><td>${E(x.name||'-')}</td><td>${E(x.phone||'-')}</td><td>${E(x.variant||'-')}</td><td>${waitStatusLabel(x.status)}</td><td>${x.createdAt?new Date(x.createdAt).toLocaleString('ar'):'-'}</td><td><div class="actions">${x.status==='waiting'?`<button class="btn primary" onclick="setWaitlistStatus(${x.id},'notified')">تم الإشعار</button>`:''}<button class="btn" onclick="setWaitlistStatus(${x.id},'${x.status==='closed'?'waiting':'closed'}')">${x.status==='closed'?'إعادة فتح':'إغلاق'}</button></div></td></tr>`))}</div>`}
async function setWaitlistStatus(id,status){await api('/api/admin/waitlist/'+id,{method:'PATCH',body:JSON.stringify({status})});toast(status==='notified'?'تم تسجيل الإشعار':'تم تحديث طلب التوفر');waitlist()}
function modal(t,b){$('#mt').textContent=t;$('#mb').innerHTML=b;$('#modal').classList.add('open')}function closeModal(){$('#modal').classList.remove('open')}
(async()=>{const token=localStorage.getItem('lf_admin_token');if(token){await showApp()}else{showLogin()}})()
